public class Codec {
    public String encode(List<String> strs) {
        return String.join(",", strs); // unsafe: ',' may appear in the data
    }

    public List<String> decode(String s) {
        return Arrays.asList(s.split(",")); // mis-splits on embedded commas
    }
}

